-- 超产审批菜单/权限增量（01-system/94 G-11 :251、付录 A #397〜#401 :685-689；06/00 SCR-PRD-034）
-- 不改已发布的 sys/V202610211405。本迁移：
--   1. CREATE OR REPLACE sys_menu_seed_rows()：付录 A 594 行（#397〜#401 插在 SCR-PRD-033 之后，原 #397 起顺延 +5）。
--      sys_init_tenant 以此为来源，之后新建租户得到 594 行；sys_init_company 按 sys_menu 全部有 permission_code 的行授权（584 行），无需改动。
--   2. sys_apply_overproduction_menu()：对已有菜单的每个租户冪等补入 5 行菜单（company_id = 0，ID = sys_seed_id，ON CONFLICT DO NOTHING，已有行不覆盖）；
--      并对各公司现有 SYSTEM_ADMIN（deleted = FALSE）只授予这 5 行（ON CONFLICT DO NOTHING）。不动已有授权，不补回撤销过的旧授权。
--   3. 以 owner 执行一次回填。
-- RLS：执行账号须为 superuser 或 BYPASSRLS（同 V202610211405）。

DO $$
DECLARE
    v_super  boolean;
    v_bypass boolean;
BEGIN
    SELECT rolsuper, rolbypassrls INTO v_super, v_bypass FROM pg_roles WHERE rolname = current_user;
    IF NOT (v_super OR v_bypass) THEN
        RAISE EXCEPTION 'V202610211406: 执行账号 % 需为 superuser 或 BYPASSRLS（FORCE RLS 表跨租户回填）', current_user;
    END IF;
END
$$;

