COMMENT ON FUNCTION public.sys_menu_seed_rows() IS 'sys_menu 种子（01-system/94 付录 A，594 行）';
REVOKE ALL ON FUNCTION public.sys_menu_seed_rows() FROM PUBLIC;

-- ---------------------------------------------------------------------------
-- 2. G-11 增量：5 行菜单 + 现有 SYSTEM_ADMIN 一次性授权（只授新 5 行）
-- ---------------------------------------------------------------------------
CREATE FUNCTION public.sys_apply_overproduction_menu()
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
DECLARE
    t        BIGINT;
    r        RECORD;
    v_parent BIGINT;
BEGIN
    -- 只处理已经种过付录 A 菜单的租户（V202610211405 已回填全部现有租户；未种菜单的租户由 sys_init_tenant 负责）
    FOR t IN SELECT DISTINCT m.tenant_id FROM sys_menu m
              WHERE m.menu_code = 'DIR-PRD' AND m.deleted = FALSE ORDER BY 1 LOOP
        FOR r IN SELECT * FROM sys_menu_seed_rows() s
                  WHERE s.menu_code IN ('SCR-PRD-034',
                                        'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-APPROVE',
                                        'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-CANCEL',
                                        'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-CREATE',
                                        'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-SUBMIT')
                  ORDER BY s.ord LOOP
            v_parent := NULL;
            SELECT m.id INTO v_parent FROM sys_menu m
             WHERE m.tenant_id = t AND m.menu_code = r.parent_code AND m.deleted = FALSE;
            IF v_parent IS NULL THEN
                RAISE EXCEPTION 'sys_apply_overproduction_menu: 父菜单 % 不存在（租户 %）', r.parent_code, t;
            END IF;
            INSERT INTO sys_menu (id, tenant_id, company_id, menu_code, menu_name, menu_type, parent_id, module_code,
                                  route_path, component_path, permission_code, icon, is_external, is_visible,
                                  sort_no, status)
            VALUES (sys_seed_id('sys_menu:' || t || ':' || r.menu_code), t, 0,
                    r.menu_code, r.menu_name, r.menu_type, v_parent, r.module_code,
                    r.route_path, NULL, r.permission_code, NULL, FALSE, r.is_visible,
                    r.sort_no, 1)
            ON CONFLICT (tenant_id, menu_code) WHERE deleted = FALSE DO NOTHING;
        END LOOP;
    END LOOP;

    -- 现有 SYSTEM_ADMIN 只授新 5 行；ID 规则同 sys_init_company
    INSERT INTO sys_role_permission (id, tenant_id, company_id, role_id, menu_id, permission_code)
    SELECT sys_seed_id('sys_role_permission:' || ro.id || ':' || m.id), ro.tenant_id, ro.company_id,
           ro.id, m.id, m.permission_code
      FROM sys_role ro
      JOIN sys_menu m ON m.tenant_id = ro.tenant_id AND m.deleted = FALSE AND m.permission_code IS NOT NULL
     WHERE ro.role_code = 'SYSTEM_ADMIN' AND ro.deleted = FALSE
       AND m.menu_code IN ('SCR-PRD-034',
                           'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-APPROVE',
                           'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-CANCEL',
                           'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-CREATE',
                           'BTN-PRODUCTION-OVERPRODUCTION-APPROVAL-SUBMIT')
    ON CONFLICT (tenant_id, company_id, role_id, menu_id) DO NOTHING;
END;
$$;
COMMENT ON FUNCTION public.sys_apply_overproduction_menu() IS
    'G-11 增量（冪等）：各租户补超产审批菜单 5 行，并只把这 5 行授给现有 SYSTEM_ADMIN；不动已有/已撤销授权。owner 执行（不走 RLS）';
REVOKE ALL ON FUNCTION public.sys_apply_overproduction_menu() FROM PUBLIC;

-- ---------------------------------------------------------------------------
-- 3. 回填（执行一次）
-- ---------------------------------------------------------------------------
SELECT public.sys_apply_overproduction_menu();

COMMENT ON FUNCTION public.sys_init_tenant(BIGINT) IS
    '租户初始化：company_id=0 的默认 sys_param、付录 A 的 sys_menu（594 行），再对各公司调用 sys_init_company；SECURITY DEFINER';
